import numpy as np
import datetime

def task_func(arr):
    a = np.asarray(arr)
    out = np.empty(a.shape, dtype=object)

    def reverse_words(x):
        if isinstance(x, str):
            return " ".join(x.split()[::-1])
        return x

    for idx in np.ndindex(a.shape):
        out[idx] = reverse_words(a[idx])

    return out
